  switchWorkingFolder: (profileId: string) => Promise<void>;
  setNotesRoot: (profileId: string, notesRoot: string) => Promise<void>;
  setTranscriptionMode: (mode: TranscriptionMode) => Promise<void>;
  saveGitSettings: (settings: {
